CREATE TABLE inspection_templates(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), version INTEGER NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), content TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE inspection_template_versions(template_id TEXT NOT NULL REFERENCES inspection_templates(id), version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, reason TEXT NOT NULL, content TEXT NOT NULL, PRIMARY KEY(template_id,version));
CREATE TABLE inspection_runs(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), template_id TEXT NOT NULL REFERENCES inspection_templates(id), template_version INTEGER NOT NULL, content TEXT NOT NULL, assignee_id TEXT NOT NULL REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('assigned','in_progress','completed','completed_with_skips','cancelled')), version INTEGER NOT NULL, updated_at TEXT NOT NULL, request_key TEXT NOT NULL, UNIQUE(created_by,request_key));
CREATE TABLE inspection_results(run_id TEXT NOT NULL REFERENCES inspection_runs(id), step_index INTEGER NOT NULL, result TEXT NOT NULL, issue_id TEXT REFERENCES issues(id), PRIMARY KEY(run_id,step_index));
CREATE TABLE inspection_events(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES inspection_runs(id), version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, UNIQUE(run_id,version));
CREATE INDEX inspection_assignee ON inspection_runs(assignee_id,status,due_at);
